import hashlib, sys, unittest
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from phase156_13dg_structured_xml_ownership_audit import extract_xml, parse_filing, valid_cusip

def raw(xml, form="SCHEDULE 13G"):
    return f"<DOCUMENT>\n<TYPE>{form}\n<FILENAME>primary_doc.xml\n<TEXT>\n<XML>\n<?xml version=\"1.0\"?>\n{xml}\n</XML>\n</TEXT>\n</DOCUMENT>".encode()

def row(data,family="13G",form="SC 13G",amend="false"):
    return {"raw_sha256":hashlib.sha256(data).hexdigest(),"family":family,"subject_cik":"0000000002","filer_cik":"0000000001","accession":"0000000001-25-000001","quarter":"2025Q1","form":form,"is_amendment":amend}

class Phase156Tests(unittest.TestCase):
    def test_xml_declaration_and_whitespace(self):
        x='<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData/></edgarSubmission>'
        self.assertEqual(extract_xml(raw(x).decode()).tag.split('}')[-1],'edgarSubmission')
    def test_cusip_check_digit(self):
        self.assertTrue(valid_cusip('40145W101')); self.assertFalse(valid_cusip('000000000'))
    def test_13g_filer_cik_is_not_reporting_person_cik(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCik>0000000002</issuerCik><issuerCusip>40145W101</issuerCusip></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle><eventDateRequiresFilingThisStatement>01/01/2025</eventDateRequiresFilingThisStatement></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>Adviser</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>100</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5.1</classPercent><soleVotingPower>0</soleVotingPower><sharedVotingPower>100</sharedVotingPower><soleDispositivePower>0</soleDispositivePower><sharedDispositivePower>100</sharedDispositivePower></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x); p=parse_filing(row(d),d); self.assertEqual(p['filer_cik'],'0000000001'); self.assertEqual(p['owners'][0]['cik'],'')
    def test_13d_reporting_person_cik_separate(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13D"><headerData><submissionType>SCHEDULE 13D</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCIK>0000000002</issuerCIK><issuerCUSIP>40145W101</issuerCUSIP></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle><dateOfEvent>01/01/2025</dateOfEvent></coverPageHeader><reportingPersons><reportingPersonInfo><reportingPersonName>Person</reportingPersonName><reportingPersonCIK>0000000003</reportingPersonCIK><aggregateAmountOwned>100</aggregateAmountOwned><percentOfClass>5.1</percentOfClass><soleVotingPower>0</soleVotingPower><sharedVotingPower>100</sharedVotingPower><soleDispositivePower>0</soleDispositivePower><sharedDispositivePower>100</sharedDispositivePower></reportingPersonInfo></reportingPersons></formData></edgarSubmission>'''
        d=raw(x,'SCHEDULE 13D');p=parse_filing(row(d,'13D','SC 13D'),d);self.assertEqual(p['owners'][0]['cik'],'0000000003')
    def test_subject_cik_mismatch_rejected(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCik>0000000008</issuerCik></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>A</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>1</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5</classPercent></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x)
        with self.assertRaisesRegex(ValueError,'subject issuer CIK/header mismatch'):parse_filing(row(d),d)
    def test_hash_mismatch_rejected(self):
        with self.assertRaisesRegex(ValueError,'raw hash mismatch'):parse_filing({"raw_sha256":"0"*64,"family":"13G"},b'x')
    def test_amendment_without_parent_remains_unresolved(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G/A</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><amendmentNo>2</amendmentNo><issuerInfo><issuerCik>0000000002</issuerCik></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>A</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>1</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5</classPercent></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x,'SCHEDULE 13G/A');p=parse_filing(row(d,form='SC 13G/A',amend='true'),d);self.assertTrue(p['is_amendment']);self.assertEqual(p['previous_accession'],'')
    def test_identical_owner_signatures_flagged_not_summed(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCik>0000000002</issuerCik></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>A</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>100.00</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5.0</classPercent><soleVotingPower>0</soleVotingPower><sharedVotingPower>100</sharedVotingPower><soleDispositivePower>0</soleDispositivePower><sharedDispositivePower>100</sharedDispositivePower></coverPageHeaderReportingPersonDetails><coverPageHeaderReportingPersonDetails><reportingPersonName>B</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>100</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5</classPercent><soleVotingPower>0</soleVotingPower><sharedVotingPower>100.00</sharedVotingPower><soleDispositivePower>0</soleDispositivePower><sharedDispositivePower>100</sharedDispositivePower></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x);p=parse_filing(row(d),d);self.assertEqual(p['repeated_signature_excess'],1);self.assertTrue(p['all_same_signature'])
    def test_new_issuerCusipNumber_field(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCik>0000000002</issuerCik><issuerCusips><issuerCusipNumber>40145W101</issuerCusipNumber></issuerCusips></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>A</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>1</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5</classPercent></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x);p=parse_filing(row(d),d);self.assertEqual(p['cusips'],['40145W101']);self.assertEqual(p['cusip_status'],'VALID_CHECKSUM')
    def test_multiple_cusips_preserved(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCik>0000000002</issuerCik><issuerCusips><issuerCusipNumber>40145W101</issuerCusipNumber><issuerCusipNumber>75704L104</issuerCusipNumber></issuerCusips></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>A</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>1</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5</classPercent></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x);p=parse_filing(row(d),d);self.assertEqual(p['cusips'],['40145W101','75704L104']);self.assertEqual(p['cusip_status'],'MULTIPLE_DISTINCT_VALUES_RETAIN_ALL')
    def test_missing_cusip_stays_missing(self):
        x='''<edgarSubmission xmlns="http://www.sec.gov/edgar/schedule13g"><headerData><submissionType>SCHEDULE 13G</submissionType><filerInfo><filer><filerCredentials><cik>0000000001</cik></filerCredentials></filer></filerInfo></headerData><formData><coverPageHeader><issuerInfo><issuerCik>0000000002</issuerCik></issuerInfo><securitiesClassTitle>Common Stock</securitiesClassTitle></coverPageHeader><coverPageHeaderReportingPersonDetails><reportingPersonName>A</reportingPersonName><reportingPersonBeneficiallyOwnedAggregateNumberOfShares>1</reportingPersonBeneficiallyOwnedAggregateNumberOfShares><classPercent>5</classPercent></coverPageHeaderReportingPersonDetails></formData></edgarSubmission>'''
        d=raw(x);self.assertEqual(parse_filing(row(d),d)['cusip_status'],'MISSING')

if __name__=='__main__':unittest.main(verbosity=2)